@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ─────────────────────────── View transitions ───────────────────────────
   Timings are shared across all three patterns so the app reads as one
   system. Exits are fast so old content stops competing for attention;
   enters are slower and start once the exit has finished. */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks during
   an animation are lost. Let them through to the live page underneath. */
::view-transition {
  pointer-events: none;
}

/* ── Shared element: thumbnail ⇄ detail hero ──
   The group animation is the morph itself — the browser interpolates position
   and size between the two. The blur mid-flight hides the artifacts of that
   interpolation. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

