import { Suspense, ViewTransition } from 'react'
import { PageTransition } from './PageTransition'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'

export default function Home() {
  return (
    // <main> sits inside the transition, not outside it, so the page slides as a
    // single snapshot. With multiple children React would snapshot each one
    // separately and derive a name per child.
    <PageTransition name="page-gallery">
      <main>
        <h1>Products</h1>
        <Suspense
          fallback={
            <ViewTransition exit="slide-down" default="none">
              <ProductGridSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="slide-up" default="none">
            <ProductGrid />
          </ViewTransition>
        </Suspense>
      </PageTransition>
    </main>
  )
}

